<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { database, makePairs, shuffle, progress } from '../store'
import { filterMemoryPairs, memoryStats, pairErrorCount } from '../pairs'
import type { MemoryFilter } from '../pairs'
import StressWord from './StressWord.vue'
import WordContext from './WordContext.vue'
const pairs = computed(() => makePairs(database.value.words))
const filter = ref<MemoryFilter>('all')
const filterItems = [{ title: 'Все пары', value: 'all' }, { title: 'Мои ошибки', value: 'mistakes' }, { title: 'Чаще всего ошибаюсь', value: 'frequent' }]
const stats = computed(() => memoryStats(database.value.words, progress.mistakeCounts, progress.mistakes))
const filteredPairs = computed(() => filterMemoryPairs(pairs.value, filter.value, stats.value))
const order = ref<string[]>([])
const index = ref(0), revealed = ref(false)
const saved = ref<string[]>([])
const displayPairs = computed(() => order.value.length ? order.value.map(id => filteredPairs.value.find(p => p.id === id)).filter((p): p is NonNullable<typeof p> => !!p) : filteredPairs.value)
const pair = computed(() => displayPairs.value[index.value % Math.max(displayPairs.value.length, 1)])
function next() { if (!displayPairs.value.length) return; index.value = (index.value + 1) % displayPairs.value.length; revealed.value = false }
function shufflePairs() { order.value = filterMemoryPairs(shuffle(filteredPairs.value), filter.value, stats.value).map(p => p.id); index.value = 0; revealed.value = false }
function toggleSaved() { if (!pair.value) return; saved.value = saved.value.includes(pair.value.id) ? saved.value.filter(id => id !== pair.value.id) : [...saved.value, pair.value.id] }
watch(filter, () => { index.value = 0; revealed.value = false; order.value = [] })
watch(() => displayPairs.value.length, () => { index.value = 0; revealed.value = false })
</script>
<template>
  <div class="page-heading"><div><router-link to="/" class="back-link"><v-icon icon="mdi-arrow-left" size="16" />К темам</router-link><h1>Вместе запоминается<span class="heading-dot">.</span></h1><p>Два слова, один созвучный акцент. Прочитай их вслух.</p></div><span class="subtle-pill">{{ pairs.length }} пар из твоей базы</span></div>
  <div class="practice-layout"><section><div class="memory-filter"><v-select v-model="filter" :items="filterItems" label="Какие пары повторим?" variant="outlined" density="comfortable" hide-details /><p class="training-description">{{ filter === 'frequent' ? 'Пары с твоими ошибками из квизов: сначала те, где суммарно больше ошибок. Число ошибок учитывается с этого обновления; прежние отметки сохранены без точного количества.' : filter === 'mistakes' ? 'Пары со словами из текущего списка ошибок. Правильный ответ в квизе убирает слово из этого списка.' : 'Все созвучные пары из твоей базы. Выбери фильтр, чтобы повторить слова, в которых ты ошибаешься.' }}</p></div><div class="memory-toolbar"><span>КАРТОЧКА {{ displayPairs.length ? index + 1 : 0 }} / {{ displayPairs.length }}</span><v-btn variant="text" prepend-icon="mdi-shuffle-variant" :disabled="!displayPairs.length" @click="shufflePairs">{{ filter === 'frequent' ? 'Перемешать равные' : 'Перемешать' }}</v-btn></div><v-card v-if="pair" class="memory-card"><div class="memory-spark">✳</div><div class="eyebrow">ЗАПОМНИ ПАРУ</div><div v-if="filter !== 'all'" class="memory-error-count">{{ pairErrorCount(pair, stats) ? 'Учтено ошибок в этой паре: ' + pairErrorCount(pair, stats) : 'Ранее отмеченная ошибка · точное число не сохранено' }}</div><div class="pair-words"><WordContext :entry="pair.a"><StressWord :word="revealed ? pair.a.correct : pair.a.word" /></WordContext><span class="pair-dash">—</span><WordContext :entry="pair.b"><StressWord :word="revealed ? pair.b.correct : pair.b.word" /></WordContext></div><p v-if="!revealed">Попробуй поставить ударения самостоятельно.</p><p v-else class="pair-explanation">Общая ударная часть: <strong>«{{ pair.tail }}»</strong>.<br>Проговори пару вместе, чтобы закрепить созвучие.</p><v-btn v-if="!revealed" color="primary" size="large" prepend-icon="mdi-eye-outline" @click="revealed = true">Показать ударения</v-btn><v-btn v-else color="primary" size="large" append-icon="mdi-arrow-right" @click="next">Следующая пара</v-btn><div class="memory-card-foot"><v-btn variant="text" :prepend-icon="saved.includes(pair.id) ? 'mdi-bookmark-check' : 'mdi-bookmark-outline'" @click="toggleSaved">{{ saved.includes(pair.id) ? 'Отмечено в этой сессии' : 'Отметить пару' }}</v-btn><v-btn v-if="!revealed" variant="text" @click="next">Пропустить <v-icon icon="mdi-arrow-right" size="17" /></v-btn></div></v-card><v-card v-else class="empty-card"><h2>{{ filter === 'all' ? 'Пары пока не найдены' : 'Нет пар с ошибками' }}</h2><p>{{ filter === 'all' ? 'В текущей базе нет слов с подходящим созвучием.' : 'В этом фильтре пока нет подходящих пар. Ошибки появляются после ответов в квизах; для некоторых слов в базе нет созвучного напарника.' }}</p><v-btn v-if="filter !== 'all'" variant="tonal" color="primary" @click="filter = 'all'">Все пары</v-btn><v-btn v-if="filter !== 'all'" to="/quiz" variant="text" color="primary">Перейти к квизам</v-btn></v-card><div class="memory-note"><v-icon icon="mdi-information-outline" size="20" /><p>Пары подобраны по совпадению части слова от ударной гласной до конца. Это приём запоминания, а не правило о корне или окончании.</p></div></section><aside class="practice-aside"><span class="aside-flower">✳</span><h3>У слов тоже<br>бывают напарники.</h3><p>Созвучия помогают удерживать ударение в памяти. Сначала вспомни знакомое слово, затем — его пару.</p><div class="aside-rule"></div><h4>Как тренироваться</h4><ol><li>Прочитай оба слова.</li><li>Поставь ударения в уме.</li><li>Открой ответ и повтори вслух.</li></ol><router-link to="/quiz">Проверить себя в квизе <v-icon icon="mdi-arrow-right" size="16" /></router-link></aside></div>
</template>
